 4→// Returns nil if the agent doesn't support token calculation or on error.
 5→// Errors are silently ignored because this runs in agent hook paths where
 6→// stderr is unreliable, and callers treat nil token usage as "no data available".
 7→func CalculateTokenUsage(ag Agent, transcriptData []byte, transcriptLinesAtStart int, subagentsDir string) *TokenUsage {
 8→	if ag == nil {
 9→		return nil
10→	}
11→	// Calculate token usage - prefer SubagentAwareExtractor to include subagent tokens
12→	if subagentExtractor, ok := ag.(SubagentAwareExtractor); ok {
13→		usage, err := subagentExtractor.CalculateTotalTokenUsage(transcriptData, transcriptLinesAtStart, subagentsDir)
14→		if err == nil {
15→			return usage
16→		}
17→	} else if calculator, ok := ag.(TokenCalculator); ok {
18→		// Fall back to basic token calculation (main transcript only)
19→		usage, err := calculator.CalculateTokenUsage(transcriptData, transcriptLinesAtStart)
20→		if err == nil {
21→			return usage
22→		}
23→	}
24→	return nil
