280→// If the remote-tracking branch (origin/entire/checkpoints/v1) exists, creates the local
281→// branch from it to preserve existing checkpoint data. Otherwise creates an empty orphan.
282→func EnsureMetadataBranch(repo *git.Repository) error {
283→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
284→
285→	// Check if local branch already exists
286→	_, err := repo.Reference(refName, true)
287→	if err == nil {
288→		return nil
289→	}
290→	if !errors.Is(err, plumbing.ErrReferenceNotFound) {
291→		return fmt.Errorf("failed to check metadata branch: %w", err)
292→	}
293→
294→	// Local branch doesn't exist — create from remote if available
295→	remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName)
296→	remoteRef, remoteErr := repo.Reference(remoteRefName, true)
297→	if remoteErr != nil && !errors.Is(remoteErr, plumbing.ErrReferenceNotFound) {
298→		return fmt.Errorf("failed to check remote metadata branch: %w", remoteErr)
299→	}
300→	if remoteErr == nil {
301→		ref := plumbing.NewHashReference(refName, remoteRef.Hash())
302→		if err := repo.Storer.SetReference(ref); err != nil {
303→			return fmt.Errorf("failed to create metadata branch from remote: %w", err)
304→		}
305→		fmt.Fprintf(os.Stderr, "✓ Created local branch '%s' from origin\n", paths.MetadataBranchName)
306→		return nil
307→	}
308→
309→	// No local or remote branch — create empty orphan
310→	emptyTree := &object.Tree{Entries: []object.TreeEntry{}}
311→	obj := repo.Storer.NewEncodedObject()
312→	if err := emptyTree.Encode(obj); err != nil {
313→		return fmt.Errorf("failed to encode empty tree: %w", err)
314→	}
315→	emptyTreeHash, err := repo.Storer.SetEncodedObject(obj)
316→	if err != nil {
317→		return fmt.Errorf("failed to store empty tree: %w", err)
318→	}
319→
320→	// Create orphan commit (no parent)
321→	now := time.Now()
322→	authorName, authorEmail := GetGitAuthorFromRepo(repo)
323→	sig := object.Signature{
324→		Name:  authorName,
325→		Email: authorEmail,
326→		When:  now,
327→	}
